// ── Lightweight markdown renderer ────────────────────────────────────────────
function renderMarkdown(text: string): React.ReactNode {
  const lines = text.split("\n");
  const nodes: React.ReactNode[] = [];
  let i = 0;

  const inlineFormat = (line: string, key: string | number): React.ReactNode => {
    // code block inline
    const parts = line.split(/(`[^`]+`)/g);
    return (
      <span key={key}>
        {parts.map((part, j) => {
          if (part.startsWith("`") && part.endsWith("`") && part.length > 2) {
            return <code key={j} className="px-1 py-0.5 rounded text-[11px] font-mono bg-muted/60 text-primary border border-border/40">{part.slice(1, -1)}</code>;
          }
          // bold **text**
          const boldParts = part.split(/(\*\*[^*]+\*\*)/g);
          return boldParts.map((bp, k) => {
            if (bp.startsWith("**") && bp.endsWith("**") && bp.length > 4) {
              return <strong key={k} className="font-semibold text-foreground">{bp.slice(2, -2)}</strong>;
            }
            // italic *text*
            const italicParts = bp.split(/(\*[^*]+\*)/g);
            return italicParts.map((ip, l) => {
              if (ip.startsWith("*") && ip.endsWith("*") && ip.length > 2) {
                return <em key={l} className="italic text-foreground/80">{ip.slice(1, -1)}</em>;
              }
              return <span key={l}>{ip}</span>;
            });
          });
        })}
      </span>
    );
  };

  while (i < lines.length) {
    const line = lines[i];

    // Fenced code block
    if (line.trim().startsWith("```")) {
      const codeLines: string[] = [];
      i++;
      while (i < lines.length && !lines[i].trim().startsWith("```")) {
        codeLines.push(lines[i]);
        i++;
      }
      nodes.push(
        <pre key={i} className="my-2 rounded-lg bg-muted/40 border border-border/40 p-3 text-xs font-mono overflow-x-auto whitespace-pre">
          {codeLines.join("\n")}
        </pre>
      );
      i++;
      continue;
    }

    // H3 ###
    if (line.startsWith("### ")) {
      nodes.push(<h3 key={i} className="text-sm font-bold text-primary mt-3 mb-1">{inlineFormat(line.slice(4), `h-${i}`)}</h3>);
      i++; continue;
    }
    // H2 ##
    if (line.startsWith("## ")) {
      nodes.push(<h2 key={i} className="text-sm font-bold text-foreground mt-4 mb-1 border-b border-border/30 pb-1">{inlineFormat(line.slice(3), `h-${i}`)}</h2>);
      i++; continue;
    }
    // H1 #
    if (line.startsWith("# ")) {
      nodes.push(<h2 key={i} className="text-base font-bold text-foreground mt-4 mb-1">{inlineFormat(line.slice(2), `h-${i}`)}</h2>);
      i++; continue;
    }
    // Horizontal rule ---
    if (/^---+$/.test(line.trim())) {
      nodes.push(<hr key={i} className="my-2 border-border/40" />);
      i++; continue;
    }
    // Bullet list
    if (line.match(/^[\s]*[-•*]\s/)) {
      const bullets: string[] = [];
      while (i < lines.length && lines[i].match(/^[\s]*[-•*]\s/)) {
        bullets.push(lines[i].replace(/^[\s]*[-•*]\s/, ""));
        i++;
      }
      nodes.push(
        <ul key={`ul-${i}`} className="my-1 space-y-0.5 pl-3">
          {bullets.map((b, bi) => (
            <li key={bi} className="flex gap-1.5 text-sm">
              <span className="text-primary mt-1 shrink-0">•</span>
              <span>{inlineFormat(b, `li-${bi}`)}</span>
            </li>
          ))}
        </ul>
      );
      continue;
    }
    // Numbered list
    if (line.match(/^[\s]*\d+\.\s/)) {
      const items: string[] = [];
      let start = parseInt(line.match(/^[\s]*(\d+)\./)?.[1] ?? "1");
      while (i < lines.length && lines[i].match(/^[\s]*\d+\.\s/)) {
        items.push(lines[i].replace(/^[\s]*\d+\.\s/, ""));
        i++;
      }
      nodes.push(
        <ol key={`ol-${i}`} className="my-1 space-y-0.5 pl-3 list-none">
          {items.map((item, ii) => (
            <li key={ii} className="flex gap-1.5 text-sm">
              <span className="text-primary/70 shrink-0 font-mono text-xs mt-0.5">{start + ii}.</span>
              <span>{inlineFormat(item, `oli-${ii}`)}</span>
            </li>
          ))}
        </ol>
      );
      continue;
    }
    // ALL-CAPS section header (CTI report style)
    if (/^[A-Z][A-Z\s&()/:]{6,}$/.test(line.trim()) && line.trim().length < 60) {
      nodes.push(
        <div key={i} className="mt-3 mb-1 text-[10px] font-bold uppercase tracking-widest text-primary/70 border-b border-border/30 pb-0.5">
          {line.trim()}
        </div>
      );
      i++; continue;
    }
    // Empty line → spacing
    if (line.trim() === "") {
      nodes.push(<div key={i} className="h-2" />);
      i++; continue;
    }
    // Normal paragraph
    nodes.push(<p key={i} className="text-sm leading-relaxed">{inlineFormat(line, `p-${i}`)}</p>);
    i++;
  }

  return <>{nodes}</>;
}

