function timeAgo(d: Date) {
  const m = Math.floor((Date.now() - d.getTime()) / 60000);
  if (m < 1) return "just now";
  if (m < 60) return `${m}m ago`;
  const h = Math.floor(m / 60);
  if (h < 24) return `${h}h ago`;
  return `${Math.floor(h / 24)}d ago`;
}

// ── Context fetch ─────────────────────────────────────────────────────────────
// Strategy: always pull the 5 most recent high/critical items as baseline context,
// then merge up to 5 keyword-matched items. Total cap 8, deduped by title.
async function fetchContext(query: string): Promise<ThreatContext[]> {
  const key = query.toLowerCase().trim();
  const cached = CONTEXT_CACHE.get(key);
  if (cached && Date.now() - cached.ts < 60_000) return cached.data;

  const FIELDS = "title,excerpt,severity,source_name,published_at,ai_summary";

  const isNpmQueryEarly = /\bnpm\b|supply.?chain|malicious package|compromis|backdoor|tanstack|shai.?hulud/i.test(key);
  // Baseline: skip unrelated critical/high items for topic-specific npm queries
  const baselinePromise = isNpmQueryEarly
    ? Promise.resolve([] as ThreatContext[])
    : supabase
        .from("threat_items")
        .select(FIELDS)
        .in("severity", ["critical", "high"])
        .order("published_at", { ascending: false })
        .limit(5)
        .then(r => (r.data ?? []) as ThreatContext[]);

  // Topic-specific: npm / supply-chain gets a dedicated DB query (not generic baseline noise)
  const isNpmQuery = /\bnpm\b|supply.?chain|malicious package|compromis|backdoor|tanstack|shai.?hulud/i.test(key);
  const keywordPromise = isNpmQuery
    ? supabase
        .from("threat_items")
        .select(FIELDS)
        .or([
          "category.eq.supply-chain",
          "title.ilike.%npm%", "title.ilike.%supply chain%", "title.ilike.%compromised%",
          "title.ilike.%malicious package%", "title.ilike.%tanstack%", "title.ilike.%shai-hulud%",
          "excerpt.ilike.%npm%", "source_name.ilike.%wiz research%", "source_name.ilike.%socket%",
        ].join(","))
        .order("fetched_at", { ascending: false })
        .limit(8)
        .then(r => (r.data ?? []) as ThreatContext[])
    : (() => {
        const stop = new Set(["give", "data", "relate", "recent", "just", "about", "compromises", "comprises"]);
        const keywords = key.split(/\s+/).filter(w => w.length > 3 && !stop.has(w)).slice(0, 4);
        return keywords.length
          ? supabase
              .from("threat_items")
              .select(FIELDS)
              .or(keywords.flatMap(k => [`title.ilike.%${k}%`, `excerpt.ilike.%${k}%`]).join(","))
              .order("fetched_at", { ascending: false })
              .limit(5)
              .then(r => (r.data ?? []) as ThreatContext[])
          : Promise.resolve([] as ThreatContext[]);
      })();

  const [baseline, keywordMatches] = await Promise.all([baselinePromise, keywordPromise]);

  // Merge: keyword matches first (most relevant), then baseline, dedup by title
  const seen = new Set<string>();
  const merged: ThreatContext[] = [];
  for (const item of [...keywordMatches, ...baseline]) {
    if (!seen.has(item.title)) {
      seen.add(item.title);
      merged.push(item);
    }
    if (merged.length >= 8) break;
  }

  CONTEXT_CACHE.set(key, { data: merged, ts: Date.now() });
  return merged;
}

function buildSystemPrompt(ctx: ThreatContext[]): string {
  const snippets = ctx.slice(0, 8).map((c, i) => {
    const detail = (c.ai_summary || c.excerpt || "").slice(0, 250).replace(/\n/g, " ");
    const age = Math.round((Date.now() - new Date(c.published_at).getTime()) / 3600000);
    const ageStr = age < 1 ? "< 1h ago" : age < 24 ? `${age}h ago` : `${Math.floor(age/24)}d ago`;
    return `[${i + 1}] ${c.title}\n    Severity: ${c.severity?.toUpperCase()} | Source: ${c.source_name} | ${ageStr}\n    ${detail}`;
  }).join("\n\n");

  return `You are **ThreatLens AI**, a senior Cyber Threat Intelligence (CTI) analyst and SOC advisor embedded in an enterprise security platform. You think and respond like a real threat analyst, not a generic chatbot.

## YOUR CAPABILITIES

You handle all of these analyst scenarios:

**SOC Alert Triage** — When given an IP, domain, hash, or CVE: check the live feed, assess risk, give first/last seen context, name associated malware or campaigns, and recommend an action (block/monitor/escalate).

**Threat Hunting** — When asked about a threat actor, malware family, or attack technique: aggregate what the feed shows, identify common IOCs and TTPs, map to MITRE ATT&CK, and highlight emerging trends.

**Email Phishing Analysis** — When given email headers, sender info, or a URL: identify spoofing, assess phishing likelihood, extract IOCs, give a verdict (Malicious/Suspicious/Safe).

**Data Breach / Leak Detection** — When given a company or domain name: check if it appears in the feed with breach-related context, classify as potential data breach, extract indicators, and recommend alerting steps.

**CISO / Executive Summary** — When asked for "today's summary", "threat overview", or "board brief": use the feed data to build a non-technical summary — top threats, affected industries, risk level, and 3 key actions. No jargon.

**IOC Correlation** — When asked if an IOC appears multiple times or across sources: count appearances, increase confidence, and classify confidence level (High/Medium/Low).

**Zero-Day / CVE Alerts** — When given a CVE: extract CVSS score, attack vector, affected products, KEV status, MITRE technique, and patch urgency. Classify as P0/P1/P2.

**Natural Language Search** — For any query about whether something is safe, malicious, or trending: look up the feed, apply security reasoning, and give a direct verdict with explanation.

**Organization Watchlist** — When asked about a specific company being monitored: report all feed mentions, any breach indicators, and recommended monitoring actions.

**Context-Aware Risk Assessment** — When asked "should I worry about this?": evaluate the organization's exposure, the threat's severity and relevance, and give a clear YES/NO with reasoning.

**AI Auto-Report** — When asked to generate a report for any threat: produce Executive Summary, Key Highlights, Attack Flow, MITRE ATT&CK table, IOCs, Impact Assessment, and Mitigation steps.

## STRICT FORMATTING RULES

- NEVER use markdown tables (no | pipe characters). Use bullet points instead.
- NEVER use --- dividers or excessive ## headers.
- Always use bullet points (•) for lists — never numbered prose paragraphs.
- Keep responses under 350 words total.
- Structure every response:
  **Summary:** [1 sentence]
  **Details:** [bullet points]
  **IOCs:** [bullet points, if any]
  **ATT&CK:** [T#### - Name, if applicable]
  **Actions:** [bullet points]
- Use **bold** for threat names, CVE IDs, and severity.
- Use \`code\` for IPs, hashes, domains.
- Cite feed items as [1], [2] inline. End with **VERDICT: [action]**.
- Today: ${new Date().toLocaleDateString("en-US", { weekday: "long", year: "numeric", month: "long", day: "numeric" })}

## LIVE THREAT FEED (${ctx.length} items, newest first)
${snippets || "(No feed data — answering from general CTI knowledge. Indicate this in your response.)"}

Respond directly and analytically. Be specific. Be actionable. Act like the analyst the SOC needs.`;
}

// ── SSE reader with proper line buffering ─────────────────────────────────────
// TCP can split SSE lines mid-line. We buffer incomplete lines across chunks.
async function readSSE(
  body: ReadableStream<Uint8Array>,
  onChunk: (text: string) => void
): Promise<void> {
  const reader = body.getReader();
  const dec = new TextDecoder();
  let buffer = "";

  while (true) {
    const { done, value } = await reader.read();
    if (done) break;

    buffer += dec.decode(value, { stream: true });
    const lines = buffer.split("\n");
    // Keep the last partial line in buffer
    buffer = lines.pop() ?? "";

    for (const line of lines) {
      if (!line.startsWith("data:")) continue;
      const raw = line.slice(5).trim();
      if (raw === "[DONE]") return;
      if (!raw) continue;
      try {
        const j = JSON.parse(raw);
        const chunk = j.choices?.[0]?.delta?.content ?? j.message?.content ?? "";
        if (chunk) onChunk(chunk);
      } catch { /* partial JSON — skip */ }
    }
  }

  // Flush remaining buffer
  if (buffer.startsWith("data:")) {
    const raw = buffer.slice(5).trim();
    if (raw && raw !== "[DONE]") {
      try {
        const j = JSON.parse(raw);
        const chunk = j.choices?.[0]?.delta?.content ?? j.message?.content ?? "";
        if (chunk) onChunk(chunk);
      } catch { /* discard */ }
    }
  }
}

// ── Supabase edge function (Groq server-side — production path) ───────────────
async function callSupabaseAi(
  messages: { role: string; content: string }[],
  onChunk: (t: string) => void,
): Promise<void> {
  const { data, error } = await supabase.functions.invoke("ai-live-intel", {
    body: { mode: "chat", messages: messages.slice(-8) },
  });
  if (error) throw new Error(error.message);
  if ((data as any)?.error) throw new Error(String((data as any).error));
  const text = String((data as any)?.content ?? "").trim();
  if (!text) throw new Error("AI returned an empty response");
  const CHUNK = 50;
  for (let i = 0; i < text.length; i += CHUNK) {
    onChunk(text.slice(i, i + CHUNK));
    if (i + CHUNK < text.length) await new Promise(r => setTimeout(r, 12));
  }
}

async function pingSupabaseAi(): Promise<boolean> {
  try {
    const { data, error } = await supabase.functions.invoke("ai-live-intel", {
      body: { mode: "chat", messages: [{ role: "user", content: "ping" }] },
    });
    return !error && !!(data as any)?.content;
  } catch {
    return false;
  }
}

// ── Groq streaming (optional local dev — browser-direct) ───────────────────────
async function callGroq(
  messages: { role: string; content: string }[],
  signal: AbortSignal,
  onChunk: (t: string) => void
): Promise<void> {
  const res = await fetch("https://api.groq.com/openai/v1/chat/completions", {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
      Authorization: `Bearer ${GROQ_KEY}`,
    },
    body: JSON.stringify({
      model: GROQ_CHAT_MODEL,
      messages,
      stream: true,
      max_tokens: 1200,
      temperature: 0.35,
    }),
    signal,
  });

  if (!res.ok) {
    const errBody = await res.text().catch(() => "");
    throw new Error(`Groq ${res.status}: ${errBody.slice(0, 120)}`);
  }
  if (!res.body) throw new Error("Groq returned no body");
  await readSSE(res.body, onChunk);
}

// ── Ollama local streaming ────────────────────────────────────────────────────
async function callOllama(
  messages: { role: string; content: string }[],
  signal: AbortSignal,
  onChunk: (t: string) => void
): Promise<void> {
  const res = await fetch(`${OLLAMA_URL}/api/chat`, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({
      model: OLLAMA_MODEL,
      messages,
      stream: true,
      options: { temperature: 0.35, num_predict: 1000 },
    }),
    signal,
  });
  if (!res.ok) throw new Error(`Ollama ${res.status}`);
  if (!res.body) throw new Error("Ollama returned no body");

  const reader = res.body.getReader();
  const dec = new TextDecoder();
  let buffer = "";

  while (true) {
    const { done, value } = await reader.read();
    if (done) break;
    buffer += dec.decode(value, { stream: true });
    const lines = buffer.split("\n");
    buffer = lines.pop() ?? "";
    for (const line of lines) {
      if (!line.trim()) continue;
      try {
        const j = JSON.parse(line);
        if (j.message?.content) onChunk(j.message.content);
        if (j.done) return;
      } catch { /* partial */ }
    }
  }
}

// ── Provider status checker ───────────────────────────────────────────────────
type ProviderStatus = "checking" | "online" | "offline" | "no-key";

export default function ThreatChat() {
  const [messages, setMessages] = useState<Message[]>([
    {
      id: "welcome",
      role: "assistant",
      content:
        "Hello! I'm **ThreatLens AI** — your dedicated cyber threat intelligence analyst and SOC advisor.\n\nI have live access to your threat feed and can act as your on-demand analyst for:\n\n**🔍 SOC Triage** — Check if an IP, domain, hash, or CVE is malicious\n**🎯 Threat Hunting** — Investigate actors, campaigns, and attack patterns\n**📧 Phishing Analysis** — Paste email headers for instant verdict\n**🏢 Breach Detection** — Ask if a company name appears in breach data\n**📊 Executive Brief** — Get a CISO-level threat summary in plain English\n**⚡ IOC Correlation** — Find related indicators across all sources\n**🛡 Zero-Day Alerts** — Get CVSS, MITRE ATT&CK, and patch guidance instantly\n\nTry asking: *\"Check IP 185.234.217.22\"* or *\"Give me today's threat summary\"*",
      timestamp: new Date(),
    },
  ]);
  const [input, setInput] = useState("");
  const [loading, setLoading] = useState(false);
  const [serverAiStatus, setServerAiStatus] = useState<ProviderStatus>("checking");
  const [localGroqStatus, setLocalGroqStatus] = useState<ProviderStatus>(GROQ_KEY ? "checking" : "no-key");
  const [ollamaStatus, setOllamaStatus] = useState<ProviderStatus>("checking");
  const [lastError, setLastError] = useState<string | null>(null);
  const [copied, setCopied] = useState<string | null>(null);
  const bottomRef = useRef<HTMLDivElement>(null);
  const abortRef = useRef<AbortController | null>(null);
  const textareaRef = useRef<HTMLTextAreaElement>(null);

  // Check providers on mount — Supabase/Groq is the production path
  useEffect(() => {
    pingSupabaseAi()
      .then(ok => setServerAiStatus(ok ? "online" : "offline"))
      .catch(() => setServerAiStatus("offline"));

    if (GROQ_KEY) {
      fetch("https://api.groq.com/openai/v1/models", {
        headers: { Authorization: `Bearer ${GROQ_KEY}` },
        signal: AbortSignal.timeout(8000),
      })
        .then(r => setLocalGroqStatus(r.ok ? "online" : "offline"))
        .catch(() => setLocalGroqStatus("offline"));
    } else {
      setLocalGroqStatus("no-key");
    }

    fetch(`${OLLAMA_URL}/api/tags`, { signal: AbortSignal.timeout(4000) })
      .then(r => setOllamaStatus(r.ok ? "online" : "offline"))
      .catch(() => setOllamaStatus("offline"));
  }, []);

  useEffect(() => {
    bottomRef.current?.scrollIntoView({ behavior: "smooth" });
  }, [messages]);

  const send = async (query?: string) => {
    const text = (query ?? input).trim();
    if (!text || loading) return;
    setInput("");
    setLastError(null);
    if (textareaRef.current) textareaRef.current.style.height = "auto";

    const userMsg: Message = {
      id: generateId(),
      role: "user",
      content: text,
      timestamp: new Date(),
    };

    const assistantId = generateId();
    setMessages(prev => [
      ...prev,
      userMsg,
      { id: assistantId, role: "assistant", content: "", timestamp: new Date() },
    ]);
    setLoading(true);

    abortRef.current = new AbortController();
    const signal = abortRef.current.signal;

    let gotContent = false;

    const onChunk = (chunk: string) => {
      gotContent = true;
      setMessages(prev =>
        prev.map(m => m.id === assistantId ? { ...m, content: m.content + chunk } : m)
      );
    };

    try {
      const ctx = await fetchContext(text);

      const history = messages
        .filter(m => m.id !== "welcome" && !m.error)
        .slice(-6)
        .map(m => ({ role: m.role, content: m.content }));

      const aiMessages = [
        { role: "system" as const, content: buildSystemPrompt(ctx) },
        ...history,
        { role: "user" as const, content: text },
      ];

      const sourceNames = [...new Set(ctx.map(c => c.source_name))].filter(Boolean).slice(0, 4);

      // Try providers: Supabase/Groq (production) → local Groq (dev) → Ollama
      let succeeded = false;

      if (serverAiStatus !== "offline") {
        try {
          await callSupabaseAi(aiMessages, onChunk);
          succeeded = true;
        } catch (e: any) {
          if (e.name === "AbortError") throw e;
          console.warn("Supabase AI failed:", e.message);
          setServerAiStatus("offline");
          setLastError(`Supabase AI: ${e.message}`);
          setMessages(prev => prev.map(m => m.id === assistantId ? { ...m, content: "" } : m));
          gotContent = false;
        }
      }

      if (!succeeded && GROQ_KEY && localGroqStatus !== "offline") {
        try {
          await callGroq(aiMessages, signal, onChunk);
          succeeded = true;
        } catch (e: any) {
          if (e.name === "AbortError") throw e;
          console.warn("Local Groq failed:", e.message);
          setLocalGroqStatus("offline");
          setLastError(`Groq: ${e.message}`);
          setMessages(prev => prev.map(m => m.id === assistantId ? { ...m, content: "" } : m));
          gotContent = false;
        }
      }

      if (!succeeded && ollamaStatus !== "offline") {
        try {
          await callOllama(aiMessages, signal, onChunk);
          succeeded = true;
        } catch (e: any) {
          if (e.name === "AbortError") throw e;
          console.warn("Ollama failed:", e.message);
          setOllamaStatus("offline");
          setLastError(`Ollama: ${e.message}`);
          setMessages(prev => prev.map(m => m.id === assistantId ? { ...m, content: "" } : m));
          gotContent = false;
        }
      }

      if (!succeeded) {
        throw new Error("All AI providers unavailable");
      }

      // If we got content, post-process and attach sources
      if (gotContent) {
        setMessages(prev =>
          prev.map(m => {
            if (m.id !== assistantId) return m;
            // Strip markdown tables (| ... | lines) — convert to bullet points
            const cleaned = m.content
              .split("\n")
              .map(line => {
                // Skip table separator lines (|---|---|)
                if (/^\|[\s-|]+\|$/.test(line.trim())) return null;
                // Convert table data rows to bullet points
                if (/^\|/.test(line.trim()) && line.includes("|")) {
                  return "• " + line.replace(/^\|/, "").replace(/\|$/, "").split("|").map(c => c.trim()).filter(Boolean).join(" · ");
                }
                return line;
              })
              .filter(l => l !== null)
              .join("\n")
              .replace(/\n{3,}/g, "\n\n")
              .trim();
            return { ...m, content: cleaned, sources: sourceNames };
          })
        );
      } else {
        // Succeeded call but no chunks streamed — empty response
        throw new Error("AI returned an empty response. Try rephrasing your question.");
      }

    } catch (err: any) {
      if (err.name === "AbortError") {
        setLoading(false);
        return;
      }

      const isNoProvider = err.message.includes("All AI providers");
      const errorContent = isNoProvider
        ? `⚠️ No AI provider is reachable right now.\n\n**Supabase AI (Groq)** (${serverAiStatus}): Edge function unavailable — ensure \`GROQ_API_KEY\` is set in Supabase secrets\n**Local Groq** (${localGroqStatus}): ${GROQ_KEY ? "Browser key configured but offline" : "Not configured (optional for dev)"}\n**Ollama** (${ollamaStatus}): Run \`ollama serve\` and pull \`${OLLAMA_MODEL}\` for local fallback`
        : `⚠️ ${err.message}`;

      setMessages(prev =>
        prev.map(m =>
          m.id === assistantId ? { ...m, content: errorContent, error: true } : m
        )
      );
    } finally {
      setLoading(false);
      abortRef.current = null;
    }
  };

  const stop = () => {
    abortRef.current?.abort();
    setLoading(false);
  };

  const clear = () => {
    setMessages([{
      id: "welcome",
      role: "assistant",
      content: "Chat cleared. How can I help you with threat intelligence?",
      timestamp: new Date(),
    }]);
    setLastError(null);
  };

  const copy = (id: string, text: string) => {
    navigator.clipboard.writeText(text);
    setCopied(id);
    setTimeout(() => setCopied(null), 2000);
  };

  const statusDot = (s: ProviderStatus) => {
    if (s === "online")   return <span className="w-1.5 h-1.5 rounded-full bg-emerald-500 animate-pulse inline-block" />;
    if (s === "checking") return <span className="w-1.5 h-1.5 rounded-full bg-yellow-500 animate-pulse inline-block" />;
    if (s === "offline")  return <span className="w-1.5 h-1.5 rounded-full bg-red-500 inline-block" />;
    return                       <span className="w-1.5 h-1.5 rounded-full bg-slate-500 inline-block" />;
  };

  const aiOnline = serverAiStatus === "online" || localGroqStatus === "online" || ollamaStatus === "online";
  const activeProvider = serverAiStatus === "online"
    ? { name: SERVER_AI_LABEL, color: "text-emerald-400" }
    : localGroqStatus === "online"
    ? { name: `Groq · ${GROQ_CHAT_MODEL}`, color: "text-emerald-400" }
    : ollamaStatus === "online"
    ? { name: `Ollama · ${OLLAMA_MODEL}`, color: "text-cyan-400" }
    : { name: "No provider active", color: "text-red-400" };

  return (
    <div className="flex flex-col h-[calc(100vh-3.5rem)]">
      {/* ── Header ─────────────────────────────────────────────────────────── */}
      <div className="border-b border-border/60 bg-background/80 backdrop-blur px-6 py-3 flex items-center gap-3 shrink-0">
        <div className="flex items-center justify-center w-9 h-9 rounded-lg bg-primary/10 border border-primary/20 shrink-0">
          <BotMessageSquare className="w-5 h-5 text-primary" />
        </div>
        <div className="flex-1 min-w-0">
          <h1 className="text-base font-bold tracking-tight flex items-center gap-2 flex-wrap">
            AI Threat Analyst
            <Badge variant="outline" className={`text-[9px] border-primary/30 ${activeProvider.color} font-mono`}>
              <Sparkles className="w-2.5 h-2.5 mr-1" />
              {activeProvider.name}
            </Badge>
          </h1>
          <p className="text-xs text-muted-foreground">Natural language queries across your live threat feed</p>
        </div>
        <div className="flex items-center gap-3 shrink-0">
          {/* Provider status pills */}
          <div className="hidden sm:flex items-center gap-2">
            <span className={`flex items-center gap-1 text-[10px] ${serverAiStatus === "online" ? "text-emerald-400" : serverAiStatus === "checking" ? "text-yellow-400" : "text-red-400"}`}>
              {statusDot(serverAiStatus)} Supabase AI
            </span>
            <span className={`flex items-center gap-1 text-[10px] ${ollamaStatus === "online" ? "text-cyan-400" : "text-slate-500"}`}>
              {statusDot(ollamaStatus)} Ollama
            </span>
          </div>
          <Button size="sm" variant="ghost" className="h-8 gap-1.5 text-xs" onClick={clear}>
            <Trash2 className="w-3.5 h-3.5" />
            Clear
          </Button>
        </div>
      </div>

      {/* ── Status banner ──────────────────────────────────────────────────── */}
      {serverAiStatus === "checking" && (
        <div className="mx-6 mt-4 shrink-0">
          <Card className="border-yellow-500/20 bg-yellow-500/5 px-4 py-2.5">
            <div className="flex items-center gap-2 text-xs text-yellow-400">
              <Loader2 className="w-3.5 h-3.5 shrink-0 animate-spin" />
              <span>Connecting to Supabase AI (Groq)…</span>
            </div>
          </Card>
        </div>
      )}
      {serverAiStatus === "offline" && localGroqStatus !== "online" && ollamaStatus !== "online" && (
        <div className="mx-6 mt-4 shrink-0">
          <Card className="border-red-500/30 bg-red-500/5 px-4 py-3">
            <div className="flex items-start gap-2 text-sm text-red-400">
              <AlertTriangle className="w-4 h-4 shrink-0 mt-0.5" />
              <div>
                <strong>AI Threat Analyst is offline.</strong>
                <p className="text-xs mt-1 text-red-400/80">
                  Groq runs server-side via Supabase — set <code className="bg-red-500/10 px-1 py-0.5 rounded text-[11px]">GROQ_API_KEY</code> in Supabase Edge Function secrets, then redeploy <code className="bg-red-500/10 px-1 py-0.5 rounded text-[11px]">ai-live-intel</code>.
                  {lastError && <span className="block mt-1 text-[10px] text-red-400/60">Error: {lastError}</span>}
                </p>
              </div>
            </div>
          </Card>
        </div>
      )}
      {serverAiStatus === "online" && (
        <div className="mx-6 mt-4 shrink-0">
          <Card className="border-emerald-500/20 bg-emerald-500/5 px-4 py-2.5">
            <div className="flex items-center gap-2 text-xs text-emerald-400">
              <Zap className="w-3.5 h-3.5 shrink-0" />
              <span>
                Connected via <strong>Supabase + Groq · {GROQ_CHAT_MODEL}</strong> — live threat DB context, ~1–3s response.
                {ollamaStatus === "online" && " Ollama available as local fallback."}
              </span>
            </div>
          </Card>
        </div>
      )}
      {serverAiStatus !== "online" && localGroqStatus === "online" && (
        <div className="mx-6 mt-4 shrink-0">
          <Card className="border-emerald-500/20 bg-emerald-500/5 px-4 py-2.5">
            <div className="flex items-center gap-2 text-xs text-emerald-400">
              <Zap className="w-3.5 h-3.5 shrink-0" />
              <span>Using local <strong>Groq · {GROQ_CHAT_MODEL}</strong> (dev mode).</span>
            </div>
          </Card>
        </div>
      )}
      {serverAiStatus !== "online" && localGroqStatus !== "online" && ollamaStatus === "online" && (
        <div className="mx-6 mt-4 shrink-0">
          <Card className="border-cyan-500/20 bg-cyan-500/5 px-4 py-2.5">
            <div className="flex items-center gap-2 text-xs text-cyan-400">
              <Wifi className="w-3.5 h-3.5 shrink-0" />
              <span>
                Using <strong>Ollama local · {OLLAMA_MODEL}</strong> — responses may be slower (30–60s) depending on your hardware.
              </span>
            </div>
          </Card>
        </div>
      )}

      {/* ── Messages ────────────────────────────────────────────────────────── */}
      <div className="flex-1 overflow-y-auto px-6 py-4 space-y-4">
        {messages.map(msg => (
          <div
            key={msg.id}
            className={`flex gap-3 ${msg.role === "user" ? "justify-end" : "justify-start"}`}
          >
            {msg.role === "assistant" && (
              <div className="flex-shrink-0 w-8 h-8 rounded-full bg-primary/10 border border-primary/20 flex items-center justify-center mt-1">
                <Shield className="w-4 h-4 text-primary" />
              </div>
            )}
            <div className={`max-w-[78%] ${msg.role === "user" ? "order-first" : ""}`}>
              <div
                className={`rounded-2xl px-4 py-3 text-sm leading-relaxed ${
                  msg.role === "user"
                    ? "bg-primary text-primary-foreground ml-auto rounded-tr-sm whitespace-pre-wrap"
                    : msg.error
                    ? "bg-destructive/10 border border-destructive/30 text-destructive rounded-tl-sm whitespace-pre-wrap"
                    : "bg-card border border-border/60 text-foreground rounded-tl-sm"
                }`}
              >
                {msg.role === "assistant" && !msg.error
                  ? renderMarkdown(msg.content)
                  : msg.content}
                {/* Typing dots while streaming */}
                {msg.role === "assistant" && loading && msg.content === "" && !msg.error && (
                  <span className="inline-flex items-center gap-1">
                    {[0, 150, 300].map(delay => (
                      <span
                        key={delay}
                        className="w-1.5 h-1.5 rounded-full bg-muted-foreground animate-bounce"
                        style={{ animationDelay: `${delay}ms` }}
                      />
                    ))}
                  </span>
                )}
              </div>
              <div className="flex items-center gap-2 mt-1 px-1">
                <span className="text-[10px] text-muted-foreground">{timeAgo(msg.timestamp)}</span>
                {msg.sources?.length ? (
                  <span className="flex items-center gap-1 text-[10px] text-muted-foreground">
                    <Database className="w-2.5 h-2.5" />
                    {msg.sources.slice(0, 3).join(", ")}
                    {msg.sources.length > 3 && ` +${msg.sources.length - 3}`}
                  </span>
                ) : null}
                {msg.role === "assistant" && msg.content && !msg.error && (
                  <button
                    onClick={() => copy(msg.id, msg.content)}
                    className="ml-auto text-muted-foreground hover:text-foreground transition"
                  >
                    {copied === msg.id
                      ? <CheckCheck className="w-3 h-3 text-green-500" />
                      : <Copy className="w-3 h-3" />}
                  </button>
                )}
              </div>
            </div>
            {msg.role === "user" && (
              <div className="flex-shrink-0 w-8 h-8 rounded-full bg-muted border border-border flex items-center justify-center mt-1">
                <User className="w-4 h-4 text-muted-foreground" />
              </div>
            )}
          </div>
        ))}
        <div ref={bottomRef} />
      </div>

      {/* ── Suggested prompts ───────────────────────────────────────────────── */}
      {messages.length === 1 && (
        <div className="px-6 pb-2 shrink-0">
          <p className="text-xs text-muted-foreground mb-2">Suggested queries:</p>
          <div className="flex flex-wrap gap-2">
            {SUGGESTED.map(s => (
              <button
                key={s}
                onClick={() => send(s)}
                disabled={loading}
                className="text-xs px-3 py-1.5 rounded-full border border-border/60 bg-card hover:border-primary/40 hover:text-primary transition-colors text-muted-foreground disabled:opacity-40"
              >
                {s}
              </button>
            ))}
          </div>
        </div>
      )}

      {/* ── Input ───────────────────────────────────────────────────────────── */}
      <div className="border-t border-border/60 bg-background/80 backdrop-blur px-6 py-4 shrink-0">
        <div className="flex items-end gap-3">
          <div className="flex-1 relative">
            <textarea
              ref={textareaRef}
              value={input}
              onChange={e => {
                setInput(e.target.value);
                e.target.style.height = "auto";
                e.target.style.height = Math.min(e.target.scrollHeight, 120) + "px";
              }}
              onKeyDown={e => {
                if (e.key === "Enter" && !e.shiftKey) {
                  e.preventDefault();
                  send();
                }
              }}
              placeholder="Ask about threats, CVEs, actors, IOCs… (Enter to send, Shift+Enter for new line)"
              disabled={loading}
              rows={1}
              className="w-full resize-none rounded-xl border border-border/60 bg-card px-4 py-3 text-sm text-foreground placeholder:text-muted-foreground focus:outline-none focus:ring-2 focus:ring-primary/40 focus:border-primary transition disabled:opacity-50 overflow-hidden"
            />
          </div>
          {loading ? (
            <Button
              onClick={stop}
              size="icon"
              variant="outline"
              className="h-10 w-10 shrink-0 border-destructive/40 text-destructive hover:bg-destructive/10"
              title="Stop generating"
            >
              <RefreshCw className="w-4 h-4 animate-spin" />
            </Button>
          ) : (
            <Button
              onClick={() => send()}
              size="icon"
              disabled={!input.trim() || !aiOnline}
              className="h-10 w-10 shrink-0"
              title="Send"
            >
              <Send className="w-4 h-4" />
            </Button>
          )}
        </div>
        <div className="mt-2 flex items-center justify-between">
          <p className="text-[10px] text-muted-foreground">
            {serverAiStatus === "online"
              ? `${SERVER_AI_LABEL} · live feed + IOC context`
              : localGroqStatus === "online"
              ? `Groq · ${GROQ_CHAT_MODEL} · live feed context`
              : ollamaStatus === "online"
              ? `Ollama local · ${OLLAMA_MODEL} · live feed context`
              : "Waiting for AI provider…"}
          </p>
          {lastError && (
            <p className="text-[10px] text-red-400 truncate max-w-xs" title={lastError}>
              Last error: {lastError}
            </p>
          )}
        </div>
      </div>
    </div>
  );
}
